class Solution:
    def maxProduct(self, nums: List[int]) -> int:
        hi = lo = best = nums[0]            # 以当前位置结尾的最大积、最小积
        for x in nums[1:]:
            if x < 0:
                hi, lo = lo, hi             # 乘负数，大小互换
            hi = max(x, hi * x)
            lo = min(x, lo * x)
            best = max(best, hi)
        return best

